async step(s) {
  const [name, target] = action(s);
  const limit = s.timeoutMs ?? STEP_MS;
  const started = performance.now();
  let timer;
  const timeout = new Promise((_, reject) => {
    // Every action but `os` waits on the library; an `os` timeout is the oracle hanging.
    const fail = name === "os" ? harness(`the OS oracle timed out after ${limit} ms`) : product(`timed out after ${limit} ms`);
    timer = setTimeout(() => reject(fail), limit);
  });
  const acting = this.act(name, target, s);
  acting.catch(() => {}); // when the timeout wins, a later failure of the step has no one left to tell
  let outcome;
  try {
    outcome = await Promise.race([acting, timeout]);
  } finally {
    clearTimeout(timer);
  }
  check(s.expect === undefined ? {} : this.resolve(s.expect), outcome, performance.now() - started);

async start(name, target, s) {
  const options = s.options === undefined ? {} : this.resolve(s.options);
  const [command, ...args] = this.resolve(target);
  const opts = { signal: this.abort.signal };
  for (const [key, v] of Object.entries(options)) {
    if (v !== null && typeof v === "object" && "$number" in v) opts[key] = Number(v.$number); // NaN, Infinity, -Infinity
    else opts[key] = key === "input" ? payload(v) : v;
  }
  if (name === "run") {
    const outcome = this.lib(async () => runFields(await this.api.run(command, args, opts)));
    if (s.await !== false) return outcome;
    outcome.catch(() => {}); // a failure surfaces when the scenario waits for it
    this.runs.set(s.as, outcome);
    return { fields: {} };
  }
  let child;
  try {
    child = this.api.spawn(command, args, opts);
  } catch (e) {
    return failure(this.api, e);
  }
  if (s.as === undefined) {
    this.loose.push(child);
  } else {
    this.vars.set(`${s.as}.pid`, [String(child.pid)]);
    this.kids.set(s.as, { child, pty: options.pty !== undefined && options.pty !== false });
  }
  return { fields: {} };

/**
 * Substitutes `${...}`: a string that is exactly one capture becomes its list (when it is not one value); inside a
 * longer string, a variable is its first value.
 */
resolve(v) {
  if (typeof v === "string") {
    const whole = /^\$\{([^}]*)\}$/.exec(v);
    const vals = whole === null ? null : this.var(whole[1]);
    return vals !== null && vals.length !== 1 ? [...vals] : this.text(v);
  }
  if (Array.isArray(v)) return v.map((x) => this.resolve(x));
  if (v !== null && typeof v === "object") return Object.fromEntries(Object.entries(v).map(([k, x]) => [k, this.resolve(x)]));
  return v;
}

text(s) {
  return s.replace(/\$\{([^}]*)\}/g, (all, name) => {
    const [first] = this.var(name);
    if (first === undefined) throw new Error(`${all} has no value yet`);
    return first;
  });
}

var(name) {
  const vals = this.vars.get(name);
  if (vals === undefined) throw new Error(`unknown variable \${${name}}`);
  return vals;
}

/** Whatever is left: abort the signal, stop every child (best effort, bounded), remove `${TMP}`. */
async cleanup(dir) {
  this.abort.abort();
  const children = [...this.kids.values()].map((k) => k.child).concat(this.loose);
  await Promise.all(children.map((c) => within((async () => c.stop({ graceMs: 0 }))(), CLEANUP_MS)));
  rmSync(dir, { recursive: true, force: true });

export async function suite({ dir, ledgerText, fixture, api, log = console.log }) {
  const ledger = new Ledger(ledgerText);
  const names = readdirSync(dir).filter((n) => n.endsWith(".json")).sort();
  if (names.length === 0) throw new Error(`no scenarios in ${dir}`);
  const sum = { passed: 0, pending: 0, ran: 0, other: 0, files: names.length, errors: [...ledger.errors] };
  const known = new Set();
  const items = new Map(); // item -> whether every scenario of it run here passed
  for (const file of names) {
    const stem = file.slice(0, -".json".length);
    const id = item(stem);
    known.add(id);
    const started = Date.now();
    let failure = null;
    let scenario;
    try {
      scenario = new Scenario(readFileSync(join(dir, file), "utf8"), stem);
    } catch (e) {
      failure = harness(`bad scenario: ${e.message}`);
    }
    if (scenario !== undefined && !scenario.applies(OS, "ts")) {
      sum.other++;
      continue;
    }

  sum.ran++;
  items.set(id, (items.get(id) ?? true) && failure === null);
  if (failure === null) {
    sum.passed++;
    log(`ok      ${stem} (${Date.now() - started} ms)`);
  } else if (failure.kind === "product" && ledger.pending(id)) {
    sum.pending++;
    log(`pending ${stem}: ${failure.message}`);
  } else {
    sum.errors.push(`${stem}: ${failure.kind === "harness" ? "harness: " : ""}${failure.message}`);
  }
}
if (sum.ran === 0) sum.errors.push("no scenario ran: every file was classified as meant for another OS or language");
sum.errors.push(...ledger.check(known, items));
for (const e of sum.errors) log(`FAIL    ${e}`);
return sum;

export function binaries() {
  const exe = OS === "windows" ? ".exe" : "";
  const target = process.env.CARGO_TARGET_DIR ?? join(root, "target");
  const find = (variable, name) => {
    const path = process.env[variable] ?? join(target, "debug", name + exe);
    if (!existsSync(path)) throw new Error(`${path} is missing: run \`cargo build --workspace --bins\` (or set ${variable})`);
    return path;
  };
  process.env.HUGR_OMNI_SUPERVISOR = find("HUGR_OMNI_SUPERVISOR", "hugr-omni-supervisor");
  return { fixture: find("HUGR_OMNI_FIXTURE", "omni-fixture") };
}

/** The package under test: `bindings/node/index.js` (CommonJS; `createRequire` reads it the same on Node, Bun and Deno). */
export const loadApi = () => createRequire(import.meta.url)("../index.js");

/** The command line that runs `script` under this runtime; `gc`: with a way to force a garbage collection (Bun has `Bun.gc`). */
export function hostCommand(script, args = [], { gc = false } = {}) {
  const flags = runtime === "deno" ? ["run", "-A", ...(gc ? ["--v8-flags=--expose-gc"] : [])] : runtime === "node" && gc ? ["--expose-gc"] : [];
  return [process.execPath, [...flags, script, ...args]];
}

/** Prints `line`, then ends the process with `code` once it is flushed: a live Child must never keep a finished run waiting. */
export function finish(line, code) {
  process.stdout.write(`${line}\n`, () => process.exit(code));

